class ConnectionPool {
  private available: Connection[] = [];

  constructor(size: number) {
    for (let i = 0; i < size; i++) this.available.push(createConnectionSync());
  }

  acquire(): Connection {
    if (this.available.length === 0) throw new Error("Pool exhausted");
    return this.available.pop()!;
  }

  release(conn: Connection) {
    conn.reset(); // critical: clear any leftover state before reuse
    this.available.push(conn);
  }
}

const pool = new ConnectionPool(10);
async function runQuery(sql: string) {
  const conn = pool.acquire();
  try {
    return await conn.query(sql);
  } finally {
    pool.release(conn); // returned, not destroyed
  }
}
